    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }

  /* Glass Morphism Effects */
  .glass {
    background: rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
  }

  .dark .glass {
    background: rgba(255, 255, 255, 0.03);
  }

  .glass-strong {
    background: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
  }

  .dark .glass-strong {
    background: rgba(255, 255, 255, 0.05);
  }

  /* Gradient Borders */
  .gradient-border {
    position: relative;
    border: 1px solid transparent;
    background: linear-gradient(hsl(var(--card)), hsl(var(--card))) padding-box,
                linear-gradient(135deg, 
                  hsl(var(--chart-1) / 0.3), 
                  hsl(var(--chart-2) / 0.3),
                  hsl(var(--chart-1) / 0.3)
                ) border-box;
  }

  /* Animated Gradients */
  @keyframes gradient-shift {
    0%, 100% {
      background-position: 0% 50%;
    }
    50% {
      background-position: 100% 50%;
    }
  }

  .animated-gradient {
    background: linear-gradient(
      135deg,
      hsl(var(--chart-1) / 0.1),
      hsl(var(--chart-2) / 0.1),
      hsl(var(--chart-3) / 0.1)
    );
    background-size: 200% 200%;
    animation: gradient-shift 8s ease infinite;
  }

  /* Geometric Background Patterns */
  .grid-pattern {
    background-image: 
      linear-gradient(hsl(var(--border)) 1px, transparent 1px),
      linear-gradient(90deg, hsl(var(--border)) 1px, transparent 1px);
    background-size: 50px 50px;
    background-position: -1px -1px;
  }

  .dot-pattern {
    background-image: radial-gradient(circle, hsl(var(--border)) 1px, transparent 1px);
    background-size: 20px 20px;
  }

  /* Floating Animation */
  @keyframes float {
    0%, 100% {
      transform: translateY(0px);
    }
    50% {
      transform: translateY(-20px);
    }
  }

  .float {
    animation: float 6s ease-in-out infinite;
    will-change: transform;
  }

  .float-delay-1 {
    animation: float 7s ease-in-out infinite;
    animation-delay: 1s;
    will-change: transform;
  }

  .float-delay-2 {
    animation: float 8s ease-in-out infinite;
    animation-delay: 2s;
    will-change: transform;
  }

  /* Cycling Gradient Animation for Hero Name */
  @keyframes gradientCycle {
    0% {
      background-position: 0% 50%;
    }
    50% {
      background-position: 100% 50%;
    }
    100% {
      background-position: 0% 50%;
    }
  }

  .gradient-cycle {
    background: linear-gradient(
      90deg,
      hsl(var(--chart-1)),
      hsl(var(--chart-2)),
      hsl(var(--chart-3)),
      hsl(var(--chart-1))
    );
    background-size: 300% 300%;
    animation: gradientCycle 8s ease infinite;
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  /* Custom Cyberpunk Scrollbar */
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }

  ::-webkit-scrollbar-track {
    background: hsl(var(--background));
    border-left: 1px solid hsl(var(--border));
  }

  ::-webkit-scrollbar-thumb {
    background: linear-gradient(
      180deg,
      hsl(var(--chart-1)),
      hsl(var(--chart-2))
    );
    border-radius: 6px;
    border: 2px solid hsl(var(--background));
  }

  ::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(
      180deg,
      hsl(var(--chart-2)),
      hsl(var(--chart-3))
    );
  }

  /* Firefox scrollbar */
  * {
    scrollbar-width: thin;
    scrollbar-color: hsl(var(--chart-1)) hsl(var(--background));
  }

  /* 3D Transform Effects */
  .card-3d {
    transform-style: preserve-3d;
    transition: transform 0.6s ease;
  }

  .card-3d:hover {
    transform: perspective(1000px) rotateY(5deg) rotateX(5deg) translateZ(20px);
  }

  .card-3d-alt:hover {
    transform: perspective(1000px) rotateY(-5deg) rotateX(5deg) translateZ(20px);
  }

  /* Respect user's motion preferences */
  @media (prefers-reduced-motion: reduce) {
    .animate-fade-in,
    .animate-fade-in-scale,
    .float,
    .float-delay-1,
    .float-delay-2,
    .animated-gradient,
    .pulse-glow,
    .gradient-cycle {
      animation: none;
    }

    .transition-smooth,
    .transition-smooth-slow {
      transition: none;
    }
  }

  /* Fade In Animations */
  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes fadeInScale {
    from {
      opacity: 0;
      transform: scale(0.95);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  .animate-fade-in {
    animation: fadeIn 0.6s ease-out;
  }

  .animate-fade-in-scale {
    animation: fadeInScale 0.5s ease-out;
  }

  /* Stagger animation delays */
  .animate-delay-100 {
    animation-delay: 100ms;
  }

  .animate-delay-200 {
    animation-delay: 200ms;
  }

  .animate-delay-300 {
    animation-delay: 300ms;
  }

  .animate-delay-400 {
    animation-delay: 400ms;
  }

  .animate-delay-500 {
    animation-delay: 500ms;
  }

  /* Cool Scroll Animations */
  @keyframes slideInFromLeft {
    from {
      opacity: 0;
      transform: translateX(-50px);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes slideInFromRight {
    from {
      opacity: 0;
      transform: translateX(50px);
    }
    to {
      opacity: 1;
      transform: translateX(0);
    }
  }

  @keyframes slideInFromBottom {
    from {
      opacity: 0;
      transform: translateY(40px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes scaleIn {
    from {
      opacity: 0;
      transform: scale(0.9);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }

  @keyframes bounceIn {
    0% {
      opacity: 0;
      transform: scale(0.3);
    }
    50% {
      opacity: 1;
      transform: scale(1.05);
    }
    70% {
      transform: scale(0.97);
    }
    100% {
      transform: scale(1);
    }
  }

  @keyframes revealIn {
    from {
      opacity: 0;
      clip-path: inset(0 100% 0 0);
    }
    to {
      opacity: 1;
      clip-path: inset(0 0 0 0);
    }
  }

  /* Animation classes */
  .animate-slide-left {
    animation: slideInFromLeft 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  }

  .animate-slide-right {
    animation: slideInFromRight 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  }

  .animate-slide-bottom {
    animation: slideInFromBottom 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  }

  .animate-scale-in {
    animation: scaleIn 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  }

  .animate-bounce-in {
    animation: bounceIn 0.8s cubic-bezier(0.68, -0.55, 0.265, 1.55) both;
  }

  .animate-reveal {
    animation: revealIn 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  }

  /* Scroll animation states */
  .scroll-animate {
    opacity: 0;
  }

  .scroll-animate.is-visible {
    opacity: 1;
  }

  /* Pulse Animation for Interactive Elements */
  @keyframes pulse-glow {
    0%, 100% {
      box-shadow: 0 0 0 0 hsl(var(--chart-1) / 0.4);
    }
    50% {
      box-shadow: 0 0 20px 5px hsl(var(--chart-1) / 0.1);
    }
  }

  .pulse-glow {
    animation: pulse-glow 2s ease-in-out infinite;
  }

  /* Smooth Transitions */
  .transition-smooth {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .transition-smooth-slow {
    transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Radial Progress */
  @keyframes progress-spin {
    from {
      stroke-dashoffset: 251.2;
    }
    to {
      stroke-dashoffset: 0;
    }
  }

  /* Geometric Shapes */
  .geometric-bg::before {
    content: "";
    position: absolute;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, hsl(var(--chart-1) / 0.05) 0%, transparent 70%);
    border-radius: 50%;
    filter: blur(60px);
    pointer-events: none;
  }

  .geometric-bg::after {
    content: "";
    position: absolute;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, hsl(var(--chart-2) / 0.05) 0%, transparent 70%);
    border-radius: 50%;
    filter: blur(60px);
    pointer-events: none;
    right: 0;
    bottom: 0;
  }
}

